180	// httpsGet fetches rawURL through tr, trusting only srv's certificate.
181	func httpsGet(t *testing.T, tr *http.Transport, srv *httptest.Server, rawURL string) (*http.Response, string) {
182		t.Helper()
183		pool := x509.NewCertPool()
184		pool.AddCert(srv.Certificate())
185		tr.TLSClientConfig = &tls.Config{RootCAs: pool}
186		t.Cleanup(tr.CloseIdleConnections)
187		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
188		defer cancel()
189		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
190		if err != nil {
191			t.Fatal(err)
192		}
193		resp, err := (&http.Client{Transport: tr}).Do(req)
194		if err != nil {
195			t.Fatalf("GET %s: %v", rawURL, err)
196		}
197		defer func() { _ = resp.Body.Close() }()
198		body, _ := io.ReadAll(resp.Body)
199		return resp, string(body)
200	}
