19	// dialProxy opens a connection to the proxy, over TLS when it serves TLS.
20	func dialProxy(t *testing.T, p *Proxy) net.Conn {
21		t.Helper()
22		u := p.URL()
23		var conn net.Conn
24		var err error
25		if u.Scheme == "https" {
26			conn, err = tls.Dial("tcp", u.Host, &tls.Config{RootCAs: p.RootCAs()})
27		} else {
28			conn, err = net.Dial("tcp", u.Host)
29		}
30		if err != nil {
31			t.Fatalf("dialing the proxy %s: %v", u, err)
32		}
33		t.Cleanup(func() { _ = conn.Close() })
34		return conn
35	}
36	
37	// connect sends a CONNECT for target, with the extra header lines, and reads
38	// the proxy's answer.
39	func connect(t *testing.T, conn net.Conn, target string, headers ...string) (*http.Response, *bufio.Reader) {
40		t.Helper()
41		req := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n", target, target)
42		for _, h := range headers {
43			req += h + "\r\n"
44		}
45		if _, err := io.WriteString(conn, req+"\r\n"); err != nil {
46			t.Fatalf("writing CONNECT: %v", err)
47		}
48		br := bufio.NewReader(conn)
49		_ = conn.SetReadDeadline(time.Now().Add(5 * time.Second))
50		resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
51		if err != nil {
52			t.Fatalf("reading the answer to CONNECT: %v", err)
53		}
54		return resp, br
55	}
56	
57	// bufConn reads through br, which may hold bytes the proxy sent right behind
58	// its answer.
59	type bufConn struct {
60		net.Conn
61		r io.Reader
62	}
63	
64	func (c *bufConn) Read(p []byte) (int, error) { return c.r.Read(p) }
