75			{"with credentials", Options{Refuse: http.StatusForbidden}, []string{"Proxy-Authorization: Basic dTpw"}, "a.corp.test:8443",
76				Request{Target: "a.corp.test:8443", ProxyAuthorization: "Basic dTpw"}},
77			{"over TLS", Options{Refuse: http.StatusForbidden, TLS: true}, nil, "example.com:443", Request{Target: "example.com:443"}},
78		}
79		for _, tt := range tests {
