		}, 10 * time.Second, nil},
		{"unreachable", reservedProxyURL, 10 * time.Second, nil},
		{"silent", func(t *testing.T) *url.URL {
			return connectproxy.Start(t, connectproxy.Options{Silent: true}).URL()
		}, 200 * time.Millisecond, nil},
		{"proxy TLS", func(t *testing.T) *url.URL {
			return connectproxy.Start(t, connectproxy.Options{TLS: true}).URL()
		}, 10 * time.Second, nil},
		{"unsupported scheme", func(t *testing.T) *url.URL { return mustURL(t, "socks5://proxy.corp:1080") }, 10 * time.Second, nil},
	}
	for _, tt := range tests {
