			_, err := dialTLS(t, testCtx(t, tt.ctxd), Dialer{Proxy: fixed(u)}, "example.com:443", nil)
			if err == nil {
				t.Fatal("DialTLS succeeded")
			}
			pe := proxyError(t, err)
			for _, text := range []string{err.Error(), fmt.Sprintf("%+v", err), fmt.Sprintf("%#v", err), pe.Proxy} {
