	proxy := connectproxy.Start(t, connectproxy.Options{
		Route: func(string) string { return srv.Listener.Addr().String() },
	})
	_, viaProxy := dialTLS(t, testCtx(t, 10*time.Second), Dialer{Proxy: fixed(proxy.URL())}, "example.com:443", nil)
	_, direct := dialTLS(t, testCtx(t, 10*time.Second), Dialer{Proxy: direct}, srv.Listener.Addr().String(), nil)
	if viaProxy == nil || direct == nil {
		t.Fatalf("errors = %v, %v; want both to fail", viaProxy, direct)
	}
	if reflect.TypeOf(viaProxy) != reflect.TypeOf(direct) {
		t.Fatalf("via proxy: %T, direct: %T; want the same kind", viaProxy, direct)
	}
}

