func TestDialTLSSelectorError(t *testing.T) {
	boom := errors.New("bad HTTPS_PROXY")
	var tr tracker
	d := Dialer{
		Proxy:       func(*url.URL) (*url.URL, error) { return nil, boom },
		DialContext: tr.DialContext,
	}
